-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "51f44f92-68a1-53ca-8a74-c57510f322e8", "source": "College Panda SAT Math 3rd edition, physical p55, chapter 4 exercise 2 question 1", "review_note": "Restored all four original choices and original could-be wording. Independently solved the no-solution condition.", "explanation": "Expanding gives (a − 6)x = b + 3. There is no solution exactly when a = 6 and b ≠ −3. Among the four choices, only D (a = 6, b = 3) gives 0x = 6. A and B each give one solution; C gives infinitely many.", "correct": "D", "release": true, "before": {"stem": "Q1. ax − b = 3(2x + 1). In the given equation, a and b are constants. If the equation has no solution, which of the following must be true? [values of a and b]", "choices": [], "correct": {"void": true}, "explanation": "The question asks which listed condition must be true, but its answer choices are missing. Restore the original choices before scoring."}, "fields": {"stem": "The equation ax − b = 3(2x + 1), where a and b are constants, has no solution. Which of the following could be the values of a and b?", "choices": [{"key": "A", "text": "a = 2 and b = −3"}, {"key": "B", "text": "a = 2 and b = 3"}, {"key": "C", "text": "a = 6 and b = −3"}, {"key": "D", "text": "a = 6 and b = 3"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}, {"id": "53c05476-878d-5178-8816-98ded6f8655d", "source": "College Panda SAT Math 3rd edition, physical p55, chapter 4 exercise 2 question 1", "review_note": "Restored all four original choices and original could-be wording. Independently solved the no-solution condition.", "explanation": "Expanding gives (a − 6)x = b + 3. There is no solution exactly when a = 6 and b ≠ −3. Among the four choices, only D (a = 6, b = 3) gives 0x = 6. A and B each give one solution; C gives infinitely many.", "correct": "D", "release": true, "before": {"stem": "Q1. ax − b = 3(2x + 1). In the given equation, a and b are constants. If the equation has no solution, which of the following must be true? [values of a and b]", "choices": [], "correct": {"void": true}, "explanation": "The question asks which listed condition must be true, but its answer choices are missing. Restore the original choices before scoring."}, "fields": {"stem": "The equation ax − b = 3(2x + 1), where a and b are constants, has no solution. Which of the following could be the values of a and b?", "choices": [{"key": "A", "text": "a = 2 and b = −3"}, {"key": "B", "text": "a = 2 and b = 3"}, {"key": "C", "text": "a = 6 and b = −3"}, {"key": "D", "text": "a = 6 and b = 3"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}, {"id": "c7c3bbef-57c5-5abe-90e2-be04d5c136cb", "source": "College Panda SAT Math 3rd edition, physical p57, chapter 4 exercise 2 question 19", "review_note": "Original asks which value could be ab, resolving the missing sign restriction in the transcription. All choices restored.", "explanation": "Expand the right side: 2(ax + b)(ax − b) = 2a²x² − 2b². Matching coefficients with 18x² − 8 gives a² = 9 and b² = 4, so ab = ±6. Of the listed values, only 6 is possible.", "correct": "A", "release": true, "before": {"stem": "Q19. 18x² − 8 = 2(ax + b)(ax − b). In the given equation, a and b are constants. If the equation is true for all values of x, what is the value of ab?", "choices": [], "correct": {"void": true}, "explanation": "Coefficient comparison gives a² = 9 and b² = 4, so ab can be 6 or −6. The stem lacks sign restrictions and the original choices are missing."}, "fields": {"stem": "For constants a and b, 18x² − 8 = 2(ax + b)(ax − b) for every real x. Which of the following could be the value of ab?", "choices": [{"key": "A", "text": "6"}, {"key": "B", "text": "9"}, {"key": "C", "text": "12"}, {"key": "D", "text": "36"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}, {"id": "0d96db51-5e91-56c8-bbf0-1bcace472c3d", "source": "College Panda SAT Math 3rd edition, physical p57, chapter 4 exercise 2 question 19", "review_note": "Original asks which value could be ab, resolving the missing sign restriction in the transcription. All choices restored.", "explanation": "Expand the right side: 2(ax + b)(ax − b) = 2a²x² − 2b². Matching coefficients with 18x² − 8 gives a² = 9 and b² = 4, so ab = ±6. Of the listed values, only 6 is possible.", "correct": "A", "release": true, "before": {"stem": "Q19. 18x² − 8 = 2(ax + b)(ax − b). In the given equation, a and b are constants. If the equation is true for all values of x, what is the value of ab?", "choices": [], "correct": {"void": true}, "explanation": "Coefficient comparison gives a² = 9 and b² = 4, so ab can be 6 or −6. The stem lacks sign restrictions and the original choices are missing."}, "fields": {"stem": "For constants a and b, 18x² − 8 = 2(ax + b)(ax − b) for every real x. Which of the following could be the value of ab?", "choices": [{"key": "A", "text": "6"}, {"key": "B", "text": "9"}, {"key": "C", "text": "12"}, {"key": "D", "text": "36"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}, {"id": "c835d321-0d09-5dd2-91c4-146244216077", "source": "College Panda SAT Math 3rd edition, physical p57, chapter 4 exercise 2 question 20", "review_note": "Restored missing original condition that b and c are positive integers, plus all four original choices.", "explanation": "Expanding gives b = a + 6 and c = 6a. Since b is an integer, a = b − 6 is an integer. Therefore c/6 = a must be an integer. The other expressions need not be integers: for a = 5, b = 11 and c = 30, they are 11/5, 30/11 and 6/5.", "correct": "A", "release": true, "before": {"stem": "Q20. (x + a)(x + 6) = x² + bx + c. In the given equation, a, b, and c are constants. Which of the following must be an integer?", "choices": [], "correct": {"void": true}, "explanation": "The question asks which expression must be an integer, but its answer choices are missing. Restore the original choices before scoring."}, "fields": {"stem": "The expression (x + a)(x + 6), where a is a constant, is equivalent to x² + bx + c, where b and c are positive integer constants. Which of the following must be an integer?", "choices": [{"key": "A", "text": "c/6"}, {"key": "B", "text": "b/a"}, {"key": "C", "text": "c/b"}, {"key": "D", "text": "6/a"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}, {"id": "b14f065a-bd3e-506b-ae40-a519eac6959c", "source": "College Panda SAT Math 3rd edition, physical p57, chapter 4 exercise 2 question 20", "review_note": "Restored missing original condition that b and c are positive integers, plus all four original choices.", "explanation": "Expanding gives b = a + 6 and c = 6a. Since b is an integer, a = b − 6 is an integer. Therefore c/6 = a must be an integer. The other expressions need not be integers: for a = 5, b = 11 and c = 30, they are 11/5, 30/11 and 6/5.", "correct": "A", "release": true, "before": {"stem": "Q20. (x + a)(x + 6) = x² + bx + c. In the given equation, a, b, and c are constants. Which of the following must be an integer?", "choices": [], "correct": {"void": true}, "explanation": "The question asks which expression must be an integer, but its answer choices are missing. Restore the original choices before scoring."}, "fields": {"stem": "The expression (x + a)(x + 6), where a is a constant, is equivalent to x² + bx + c, where b and c are positive integer constants. Which of the following must be an integer?", "choices": [{"key": "A", "text": "c/6"}, {"key": "B", "text": "b/a"}, {"key": "C", "text": "c/b"}, {"key": "D", "text": "6/a"}], "type": "mcq", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260929' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260929','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260929','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-29-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-29-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-29-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260929','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260929'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260929')) AS result;
